         <!-- Disassembly of the front brakes --><dmRef applicRefId=\"app-0001\">\n                     <dmRefIdent>\n                        <dmCode modelIdentCode=\"S1000DBIKE\"\n                                systemDiffCode=\"AAA\"\n                                systemCode=\"DA1\"\n                                subSystemCode=\"2\"\n                                subSubSystemCode=\"0\"\n                                assyCode=\"00\"\n                                disassyCode=\"00\"\n                                disassyCodeVariant=\"AA\"\n                                infoCode=\"520\"\n                                infoCodeVariant=\"A\"\n                                itemLocationCode=\"A\"/>\n                     </dmRefIdent>\n                  </dmRef>\n                  <!-- Disassembly of the fork --><dmRef applicRefId=\"app-0001\">\n                     <dmRefIdent>\n                        <dmCode modelIdentCode=\"S1000DBIKE\"\n                                systemDiffCode=\"AAA\"\n                                systemCode=\"D00\"\n                                subSystemCode=\"0\"\n                                subSubSystemCode=\"0\"\n                                assyCode=\"01\"\n                                disassyCode=\"00\"\n                                disassyCodeVariant=\"AA\"\n                                infoCode=\"520\"\n                                infoCodeVariant=\"A\"\n                                itemLocationCode=\"A\"/>\n                     </dmRefIdent>\n                  </dmRef>\n                  <!-- Shortening of the wheel axis --><dmRef applicRefId=\"app-0001\">\n                     <dmRefIdent>\n                        <dmCode modelIdentCode=\"S1000DBIKE\"\n                                systemDiffCode=\"AAA\"\n                                systemCode=\"D00\"\n                                subSystemCode=\"0\"\n                                subSubSystemCode=\"0\"\n                                assyCode=\"01\"\n                                disassyCode=\"00\"\n                                disassyCodeVariant=\"AA\"\n                                infoCode=\"93A\"\n                                infoCodeVariant=\"A\"\n                                itemLocationCode=\"A\"/>\n                     </dmRefIdent>\n                  </dmRef>\n                  <!-- Assembly of the new fork for Mk1--><dmRef applicRefId=\"app-0002\">\n                     <dmRefIdent>\n                        <dmCode modelIdentCode=\"S1000DBIKE\"\n                                systemDiffCode=\"AAA\"\n                                systemCode=\"D00\"\n                                subSystemCode=\"0\"\n                                subSubSystemCode=\"0\"\n                                assyCode=\"01\"\n                                disassyCode=\"00\"\n                                disassyCodeVariant=\"AA\"\n                                infoCode=\"720\"\n                                infoCodeVariant=\"A\"\n                                itemLocationCode=\"A\"/>\n                     </dmRefIdent>\n                  </dmRef>\n                  <!-- Assembly of the spacer --><dmRef applicRefId=\"app-0002\">\n                     <dmRefIdent>\n                        <dmCode modelIdentCode=\"S1000DBIKE\"\n                                systemDiffCode=\"AAA\"\n                                systemCode=\"DA2\"\n                                subSystemCode=\"4\"\n                                subSubSystemCode=\"0\"\n                                assyCode=\"00\"\n                                disassyCode=\"00\"\n                                disassyCodeVariant=\"AA\"\n                                infoCode=\"720\"\n                                infoCodeVariant=\"A\"\n                                itemLocationCode=\"A\"/>\n                     </dmRefIdent>\n                  </dmRef>\n                  <!-- Assembly of the new fork for Mk9--><dmRef applicRefId=\"app-0003\">\n                     <dmRefIdent>\n                        <dmCode modelIdentCode=\"S1000DBIKE\"\n                                systemDiffCode=\"AAA\"\n                                systemCode=\"D00\"\n                                subSystemCode=\"0\"\n                                subSubSystemCode=\"0\"\n                                assyCode=\"01\"\n                                disassyCode=\"00\"\n                                disassyCodeVariant=\"AB\"\n                                infoCode=\"720\"\n                                infoCodeVariant=\"A\"\n                                itemLocationCode=\"A\"/>\n                     </dmRefIdent>\n                  </dmRef>\n                  <!-- Assembly of the front brakes --><dmRef applicRefId=\"app-0001\">\n                     <dmRefIdent>\n                        <dmCode modelIdentCode=\"S1000DBIKE\"\n                                systemDiffCode=\"AAA\"\n                                systemCode=\"DA1\"\n                                subSystemCode=\"2\"\n                                subSubSystemCode=\"0\"\n                                assyCode=\"00\"\n                                disassyCode=\"00\"\n                                disassyCodeVariant=\"AA\"\n                                infoCode=\"720\"\n                                infoCodeVariant=\"A\"\n                                itemLocationCode=\"A\"/>\n                     </dmRefIdent>\n                  </dmRef>\n                  <!-- Assembly of the front wheel --><dmRef applicRefId=\"app-0001\">\n                     <dmRefIdent>\n                        <dmCode modelIdentCode=\"S1000DBIKE\"\n                                systemDiffCode=\"AAA\"\n                                systemCode=\"DA0\"\n                                subSystemCode=\"3\"\n                                subSubSystemCode=\"0\"\n                                assyCode=\"00\"\n                                disassyCode=\"00\"\n                                disassyCodeVariant=\"AA\"\n                                infoCode=\"720\"\n                                infoCodeVariant=\"A\"\n                                itemLocationCode=\"A\"/>\n                     </dmRefIdent>\n                  </dmRef>\n                  <!-- Testing of the new fork --><dmRef applicRefId=\"app-0001\">\n                     <dmRefIdent>\n                        <dmCode modelIdentCode=\"S1000DBIKE\"\n                                systemDiffCode=\"AAA\"\n                                systemCode=\"D00\"\n                                subSystemCode=\"0\"\n                                subSubSystemCode=\"0\"\n                                assyCode=\"01\"\n                                disassyCode=\"00\"\n                                disassyCodeVariant=\"AA\"\n                                infoCode=\"341\"\n                                infoCodeVariant=\"A\"\n                                itemLocationCode=\"A\"/>\n                     </dmRefIdent>\n                  </dmRef>\n               </refs>\n            </sbApprovedDm>\n            <!-- EPWG add sbReplacementSb --><sbReplacementSb id=\"SPEC-0007\">\n               <refs>\n                  <dmRef>\n                     <dmRefIdent>\n                        <dmCode modelIdentCode=\"S1000DBIKE\"\n                                systemDiffCode=\"AAA\"\n                                systemCode=\"D00\"\n                                subSystemCode=\"0\"\n                                subSubSystemCode=\"0\"\n                                assyCode=\"09\"\n                                disassyCode=\"00\"\n                                disassyCodeVariant=\"AA\"\n                                infoCode=\"930\"\n                                infoCodeVariant=\"A\"\n                                itemLocationCode=\"A\"/>\n                     </dmRefIdent>\n                  </dmRef>\n               </refs>\n            </sbReplacementSb>\n            <!-- EPWG end add sbReplacementSb --><genericPropertyGroup>\n               <genericProperty id=\"id-0003\" genericPropertyType=\"gpt01\" genericPropertyFlag=\"1\"/>\n               <!-- \"gpt01\" means \"Passenger comfort affected\" --><genericProperty id=\"id-0004\" genericPropertyType=\"gpt04\" genericPropertyFlag=\"1\"/>\n               <!-- \"gpt04\" means \"Structural Life Extension\" --><genericProperty id=\"id-0005\" genericPropertyType=\"gpt06\" genericPropertyFlag=\"1\"/>\n               <!-- \"gpt06\" means \"Product Operation Affected\" --></genericPropertyGroup>\n         </sbManagementInfo>\n         <sbRevisionInfo><!-- Every title in sbTopic, gives the meaning of the @sbTopicType value --><sbTopic sbTopicType=\"sbtt23\">\n               <title>Revision history</title>\n               <sbTopicContent><!-- EPWG add superScript --><para id=\"SPEC-0013\">This document is the 1<superScript>st</superScript>issue of the Service Bulletin</para>\n                  <!-- EPWG end add superScript --></sbTopicContent>\n            </sbTopic>\n            <sbTopic sbTopicType=\"sbtt24\">\n               <title>Revision sequence</title>\n               <sbTopicContent>\n                  <para>Original Issue date <internalRef internalRefId=\"id-0016\"/>\n                  </para>\n               </sbTopicContent>\n            </sbTopic>\n         </sbRevisionInfo>\n         <sbSummary>\n            <sbTopic sbTopicType=\"sbtt07\">\n               <title>Reason</title>\n               <sbTopicContent>\n                  <para>A lot of customers asked for the improvement of the front hanging in order to use the bike in more severe conditions.</para>\n               </sbTopicContent>\n            </sbTopic>\n            <sbTopic sbTopicType=\"sbtt08\">\n               <title>Description</title>\n               <sbTopicContent>\n                  <para>Replacement of the fork</para>\n               </sbTopicContent>\n            </sbTopic>\n            <sbTopic sbTopicType=\"sbtt09\">\n               <title>Compliance</title>\n               <sbTopicContent>\n                  <para>\n                     <internalRef internalRefId=\"id-0001\"/>\n                  </para>\n               </sbTopicContent>\n            </sbTopic>\n            <sbTopic sbTopicType=\"sbtt05\">\n               <title>Applicability</title>\n               <sbTopicContent>\n                  <para applicRefId=\"app-0001\">This Service Bulletin is applicable to bikes manufactured between 01/05/2001 and 30/09/2009</para>\n                  <para applicRefId=\"app-0002\">Configuration no. 1 covers mountain bicycle Mountain storm version Mk1</para>\n                  <para applicRefId=\"app-0003\">Configuration no. 2 covers mountain bicycle Brook trekker version Mk9</para>\n               </sbTopicContent>\n            </sbTopic>\n            <sbTopic sbTopicType=\"sbtt06\">\n               <title>Concurrent Requirements</title>\n               <noInfo/>\n            </sbTopic>\n            <sbTopic sbTopicType=\"sbtt11\">\n               <title>Manpower</title>\n               <sbTopicContent>\n                  <table applicRefId=\"app-0002\">\n                     <tgroup cols=\"2\">\n                        <colspec colname=\"col1\" colwidth=\"20*\"/>\n                        <colspec colname=\"col2\" colwidth=\"80*\"/>\n                        <spanspec namest=\"col1\" nameend=\"col2\" spanname=\"whole\"/>\n                        <thead>\n                           <row>\n                              <entry spanname=\"whole\">\n                                 <para>\n                                    <dmRef>\n                                       <dmRefIdent>\n                                          <dmCode modelIdentCode=\"S1000DBIKE\"\n                                                  systemDiffCode=\"AAA\"\n                                                  systemCode=\"D00\"\n                                                  subSystemCode=\"0\"\n                                                  subSubSystemCode=\"0\"\n                                                  assyCode=\"01\"\n                                                  disassyCode=\"00\"\n                                                  disassyCodeVariant=\"AA\"\n                                                  infoCode=\"933\"\n                                                  infoCodeVariant=\"A\"\n                                                  itemLocationCode=\"A\"/>\n                                       </dmRefIdent>\n                                    </dmRef>\n                                 </para>\n                              </entry>\n                           </row>\n                        </thead>\n                        <tbody>\n                           <row>\n                              <entry colname=\"col1\">\n                                 <para>Total workload</para>\n                              </entry>\n                              <entry colname=\"col2\">\n                                 <para>\n                                    <internalRef internalRefId=\"id-0008\"/>\n                                 </para>\n                              </entry>\n                           </row>\n                           <row>\n                              <entry colname=\"col1\">\n                                 <para>Estimated time</para>\n                              </entry>\n                              <entry colname=\"col2\">\n                                 <para>\n                                    <internalRef internalRefId=\"id-0009\"/>\n                                 </para>\n                              </entry>\n                           </row>\n                        </tbody>\n                     </tgroup>\n                  </table>\n                  <table applicRefId=\"app-0003\">\n                     <tgroup cols=\"2\">\n                        <colspec colname=\"col1\" colwidth=\"20*\"/>\n                        <colspec colname=\"col2\" colwidth=\"80*\"/>\n                        <spanspec namest=\"col1\" nameend=\"col2\" spanname=\"whole\"/>\n                        <thead>\n                           <row>\n                              <entry spanname=\"whole\">\n                                 <para>\n                                    <dmRef>\n                                       <dmRefIdent>\n                                          <dmCode modelIdentCode=\"S1000DBIKE\"\n                                                  systemDiffCode=\"AAA\"\n                                                  systemCode=\"D00\"\n                                                  subSystemCode=\"0\"\n                                                  subSubSystemCode=\"0\"\n                                                  assyCode=\"01\"\n                                                  disassyCode=\"00\"\n                                                  disassyCodeVariant=\"AA\"\n                                                  infoCode=\"933\"\n                                                  infoCodeVariant=\"A\"\n                                                  itemLocationCode=\"A\"/>\n                                       </dmRefIdent>\n                                    </dmRef>\n                                 </para>\n                              </entry>\n                           </row>\n                        </thead>\n                        <tbody>\n                           <row>\n                              <entry colname=\"col1\">\n                                 <para>Total workload</para>\n                              </entry>\n                              <entry colname=\"col2\">\n                                 <para>\n                                    <internalRef internalRefId=\"id-0011\"/>\n                                 </para>\n                              </entry>\n                           </row>\n                           <row>\n                              <entry colname=\"col1\">\n                                 <para>Estimated time</para>\n                              </entry>\n                              <entry colname=\"col2\">\n                                 <para>\n                                    <internalRef internalRefId=\"id-0012\"/>\n                                 </para>\n                              </entry>\n                           </row>\n                        </tbody>\n                     </tgroup>\n                  </table>\n               </sbTopicContent>\n            </sbTopic>\n            <sbTopic sbTopicType=\"sbtt17\">\n               <title>Industry Support Information</title>\n               <sbTopicContent>\n                  <para>For any issue with the fork assembly, please contact your local retailer.</para>\n                  <!-- EPWG add acronym, acronymTerm, acronymDefinition --><para>The <acronym id=\"SPEC-0009\">\n                        <acronymTerm>UK MoD</acronymTerm>\n                        <acronymDefinition id=\"acr-0001\">Ministry of Defence (United Kingdom)</acronymDefinition>\n                     </acronym> only provides assistance via its network of retailers.</para>\n                  <!-- EPWG end add acronym, acronymTerm, acronymDefinition --></sbTopicContent>\n            </sbTopic>\n            <sbTopic sbTopicType=\"sbtt19\">\n               <title>General evaluation</title>\n               <sbTopicContent>\n                  <table>\n                     <tgroup cols=\"2\">\n                        <colspec colname=\"col1\" colwidth=\"20*\"/>\n                        <colspec colname=\"col2\" colwidth=\"80*\"/>\n                        <spanspec namest=\"col1\" nameend=\"col2\" spanname=\"whole\"/>\n                        <thead>\n                           <row>\n                              <entry spanname=\"whole\">\n                                 <para>EVALUATION TABLE</para>\n                              </entry>\n                           </row>\n                        </thead>\n                        <tbody>\n                           <row>\n                              <entry colname=\"col1\">\n                                 <para>Passenger comfort affected</para>\n                              </entry>\n                              <entry colname=\"col2\">\n                                 <para>\n                                    <internalRef internalRefId=\"id-0003\"/>\n                                 </para>\n                              </entry>\n                           </row>\n                           <row>\n                              <entry colname=\"col1\">\n                                 <para>Structural life extended</para>\n                              </entry>\n                              <entry colname=\"col2\">\n                                 <para>\n                                    <internalRef internalRefId=\"id-0004\"/>\n                                 </para>\n                              </entry>\n                           </row>\n                           <row>\n                              <entry colname=\"col1\">\n                                 <para>Bike operation affected</para>\n                              </entry>\n                              <entry colname=\"col2\">\n                                 <para>\n                                    <internalRef internalRefId=\"id-0005\"/>\n                                 </para>\n                              </entry>\n                           </row>\n                        </tbody>\n                     </tgroup>\n                  </table>\n               </sbTopicContent>\n            </sbTopic>\n         </sbSummary>\n         <sbPlanningInfo>\n            <sbTopic sbTopicType=\"sbtt05\">\n               <title>Applicability</title>\n               <sbTopicContent>\n                  <para applicRefId=\"app-0001\">This Service Bulletin is applicable to bikes manufactured between 01/05/2001 and 30/09/2009</para>\n                  <para applicRefId=\"app-0002\">The S/N of the impacted bikes are : <!-- Mountain storm models --><identNumber>\n                        <manufacturerCode>U8025</manufacturerCode>\n                        <partAndSerialNumber>\n                           <partNumber/>\n                           <serialNumber serialNumberValue=\"1B070701\" serialNumberForm=\"single\"/>\n                        </partAndSerialNumber>\n                     </identNumber>\n                  </para>\n                  <para applicRefId=\"app-0003\">The S/N of the impacted bikes are : <!-- Brook trekker models --><identNumber>\n                        <manufacturerCode>U8025</manufacturerCode>\n                        <partAndSerialNumber>\n                           <partNumber/>\n                           <serialNumber serialNumberValue=\"1B070643\" serialNumberForm=\"single\"/>\n                        </partAndSerialNumber>\n                     </identNumber>\n                     <identNumber>\n                        <manufacturerCode>U8025</manufacturerCode>\n                        <partAndSerialNumber>\n                           <partNumber/>\n                           <serialNumber serialNumberValue=\"1B070644\" serialNumberForm=\"single\"/>\n                        </partAndSerialNumber>\n                     </identNumber>\n                  </para>\n                  <para applicRefId=\"app-0002\">Configuration no. 1 covers mountain bicycle Mountain storm version Mk1</para>\n                  <para applicRefId=\"app-0003\">Configuration no. 2 covers mountain bicycle Brook trekker version Mk9</para>\n               </sbTopicContent>\n            </sbTopic>\n            <sbTopic sbTopicType=\"sbtt06\">\n               <title>Concurrent Requirements</title>\n               <noInfo/>\n            </sbTopic>\n            <sbTopic sbTopicType=\"sbtt07\">\n               <title>Reason</title>\n               <sbTopicContent>\n                  <levelledPara>\n                     <para>Objective :</para>\n                     <levelledPara>\n                        <para>Improvement of the bike's front hanging.</para>\n                     </levelledPara>\n                  </levelledPara>\n                  <levelledPara>\n                     <para>Problem and effect :</para>\n                     <levelledPara>\n                        <para>A lot of customers would like to use the bike in more severe conditions.</para>\n                     </levelledPara>\n                  </levelledPara>\n                  <levelledPara>\n                     <para>Solution :</para>\n                     <levelledPara>\n                        <para>Replacement of the fork.</para>\n                     </levelledPara>\n                  </levelledPara>\n               </sbTopicContent>\n            </sbTopic>\n            <sbTopic sbTopicType=\"sbtt08\">\n               <title>Description</title>\n               <sbTopicContent>\n                  <para>Replacement of the original fork</para>\n                  <levelledParaAlts id=\"SPEC-0017\"><!-- EPWG: Added levelledParaAlts --><levelledPara applicRefId=\"app-0002\">\n                        <para>by telescopic fork with a 140 mm clearance</para>\n                     </levelledPara>\n                     <levelledPara applicRefId=\"app-0003\">\n                        <para>by telescopic fork with a 100 mm clearance</para>\n                     </levelledPara>\n                  </levelledParaAlts>\n               </sbTopicContent>\n            </sbTopic>\n            <sbTopic sbTopicType=\"sbtt09\">\n               <title>Compliance</title>\n               <sbTopicContent>\n                  <levelledPara>\n                     <title>Compliance</title>\n                     <para>\n                        <internalRef internalRefId=\"id-0001\"/>\n                     </para>\n                  </levelledPara>\n                  <levelledPara>\n                     <para>The modification should be made in accordance with the customer's availability, but within the following limits (before marked wear of the frame)</para>\n                     <table>\n                        <title>Accomplishment time scale</title>\n                        <tgroup cols=\"2\">\n                           <colspec colname=\"col1\" colwidth=\"50*\"/>\n                           <colspec colname=\"col2\" colwidth=\"50*\"/>\n                           <thead>\n                              <row>\n                                 <entry colname=\"col1\">\n                                    <para>Limit</para>\n                                 </entry>\n                                 <entry colname=\"col2\">\n                                    <para>Grace period</para>\n                                 </entry>\n                              </row>\n                           </thead>\n                           <tbody>\n                              <row>\n                                 <entry colname=\"col1\">\n                                    <para>\n                                       <internalRef internalRefId=\"id-0017\"/>\n                                    </para>\n                                 </entry>\n                                 <entry colname=\"col2\">\n                                    <para>\n                                       <internalRef internalRefId=\"id-0018\"/>\n                                    </para>\n                                 </entry>\n                              </row>\n                           </tbody>\n                        </tgroup>\n                     </table>\n                  </levelledPara>\n               </sbTopicContent>\n            </sbTopic>\n            <sbTopic sbTopicType=\"sbtt10\">\n               <title>Approval</title>\n               <sbTopicContent>\n                  <para>This modification has been approved and certified in conformity with the requirements of the S1000D community.</para>\n                  <para>Approval No. <internalRef internalRefId=\"id-0015\"/>.</para>\n               </sbTopicContent>\n            </sbTopic>\n            <sbTopic sbTopicType=\"sbtt11\">\n               <title>Manpower</title>\n               <sbTopicContent>\n                  <table applicRefId=\"app-0002\">\n                     <tgroup cols=\"2\">\n                        <colspec colname=\"col1\" colwidth=\"20*\"/>\n                        <colspec colname=\"col2\" colwidth=\"80*\"/>\n                        <spanspec namest=\"col1\" nameend=\"col2\" spanname=\"whole\"/>\n                        <thead>\n                           <row>\n                              <entry spanname=\"whole\">\n                                 <para>\n                                    <dmRef>\n                                       <dmRefIdent>\n                                          <dmCode modelIdentCode=\"S1000DBIKE\"\n                                                  systemDiffCode=\"AAA\"\n                                                  systemCode=\"D00\"\n                                                  subSystemCode=\"0\"\n                                                  subSubSystemCode=\"0\"\n                                                  assyCode=\"01\"\n                                                  disassyCode=\"00\"\n                                                  disassyCodeVariant=\"1A\"\n                                                  infoCode=\"933\"\n                                                  infoCodeVariant=\"A\"\n                                                  itemLocationCode=\"A\"/>\n                                       </dmRefIdent>\n                                    </dmRef>\n                                 </para>\n                              </entry>\n                           </row>\n                        </thead>\n                        <tbody>\n                           <row>\n                              <entry colname=\"col1\">\n                                 <para>Job Set-up</para>\n                              </entry>\n                              <entry colname=\"col2\">\n                                 <para>\n                                    <quantity quantityType=\"qty04\"><!-- \"qty04\" means \"Time\" --><quantityGroup>\n                                          <quantityValue quantityUnitOfMeasure=\"min\">5</quantityValue>\n                                       </quantityGroup>\n                                    </quantity>\n                                 </para>\n                              </entry>\n                           </row>\n                           <row>\n                              <entry colname=\"col1\">\n                                 <para>Removal</para>\n                              </entry>\n                              <entry colname=\"col2\">\n                                 <para>\n                                    <quantity quantityType=\"qty04\"><!-- \"qty04\" means \"Time\" --><quantityGroup>\n                                          <quantityValue quantityUnitOfMeasure=\"min\">20</quantityValue>\n                                       </quantityGroup>\n                                    </quantity>\n                                 </para>\n                              </entry>\n                           </row>\n                           <row>\n                              <entry colname=\"col1\">\n                                 <para>Install</para>\n                              </entry>\n                              <entry colname=\"col2\">\n                                 <para>\n                                    <quantity quantityType=\"qty04\"><!-- \"qty04\" means \"Time\" --><quantityGroup>\n                                          <quantityValue quantityUnitOfMeasure=\"min\">60</quantityValue>\n                                       </quantityGroup>\n                                    </quantity>\n                                 </para>\n                              </entry>\n                           </row>\n                           <row>\n                              <entry colname=\"col1\">\n                                 <para>Testing</para>\n                              </entry>\n                              <entry colname=\"col2\">\n                                 <para>\n                                    <quantity quantityType=\"qty04\"><!-- \"qty04\" means \"Time\" --><quantityGroup>\n                                          <quantityValue quantityUnitOfMeasure=\"min\">5</quantityValue>\n                                       </quantityGroup>\n                                    </quantity>\n                                 </para>\n                              </entry>\n                           </row>\n                           <row>\n                              <entry colname=\"col1\">\n                                 <para>Total workload</para>\n                              </entry>\n                              <entry colname=\"col2\">\n                                 <para>\n                                    <internalRef internalRefId=\"id-0008\"/>\n                                 </para>\n                              </entry>\n                           </row>\n                           <row>\n                              <entry colname=\"col1\">\n                                 <para>Estimated time</para>\n                              </entry>\n                              <entry colname=\"col2\">\n                                 <para>\n                                    <internalRef internalRefId=\"id-0009\"/>\n                                 </para>\n                              </entry>\n                           </row>\n                        </tbody>\n                     </tgroup>\n                  </table>\n                  <table applicRefId=\"app-0003\">\n                     <tgroup cols=\"2\">\n                        <colspec colname=\"col1\" colwidth=\"20*\"/>\n                        <colspec colname=\"col2\" colwidth=\"80*\"/>\n                        <spanspec namest=\"col1\" nameend=\"col2\" spanname=\"whole\"/>\n                        <thead>\n                           <row>\n                              <entry spanname=\"whole\">\n                                 <para>\n                                    <dmRef>\n                                       <dmRefIdent>\n                                          <dmCode modelIdentCode=\"S1000DBIKE\"\n                                                  systemDiffCode=\"AAA\"\n                                                  systemCode=\"D00\"\n                                                  subSystemCode=\"0\"\n                                                  subSubSystemCode=\"0\"\n                                                  assyCode=\"01\"\n                                                  disassyCode=\"00\"\n                                                  disassyCodeVariant=\"AA\"\n                                                  infoCode=\"933\"\n                                                  infoCodeVariant=\"A\"\n                                                  itemLocationCode=\"A\"/>\n                                       </dmRefIdent>\n                                    </dmRef>\n                                 </para>\n                              </entry>\n                           </row>\n                        </thead>\n                        <tbody>\n                           <row>\n                              <entry colname=\"col1\">\n                                 <para>Job Set-up</para>\n                              </entry>\n                              <entry colname=\"col2\">\n                                 <para>\n                                    <quantity quantityType=\"qty04\"><!-- \"qty04\" means \"Time\" --><quantityGroup>\n                                          <quantityValue quantityUnitOfMeasure=\"min\">5</quantityValue>\n                                       </quantityGroup>\n                                    </quantity>\n                                 </para>\n                              </entry>\n                           </row>\n                           <row>\n                              <entry colname=\"col1\">\n                                 <para>Removal</para>\n                              </entry>\n                              <entry colname=\"col2\">\n                                 <para>\n                                    <quantity quantityType=\"qty04\"><!-- \"qty04\" means \"Time\" --><quantityGroup>\n                                          <quantityValue quantityUnitOfMeasure=\"min\">20</quantityValue>\n                                       </quantityGroup>\n                                    </quantity>\n                                 </para>\n                              </entry>\n                           </row>\n                           <row>\n                              <entry colname=\"col1\">\n                                 <para>Install</para>\n                              </entry>\n                              <entry colname=\"col2\">\n                                 <para>\n                                    <quantity quantityType=\"qty04\"><!-- \"qty04\" means \"Time\" --><quantityGroup>\n                                          <quantityValue quantityUnitOfMeasure=\"min\">30</quantityValue>\n                                       </quantityGroup>\n                                    </quantity>\n                                 </para>\n                              </entry>\n                           </row>\n                           <row>\n                              <entry colname=\"col1\">\n                                 <para>Testing</para>\n                              </entry>\n                              <entry colname=\"col2\">\n                                 <para>\n                                    <quantity quantityType=\"qty04\"><!-- \"qty04\" means \"Time\" --><quantityGroup>\n                                          <quantityValue quantityUnitOfMeasure=\"min\">5</quantityValue>\n                                       </quantityGroup>\n                                    </quantity>\n                                 </para>\n                              </entry>\n                           </row>\n                           <row>\n                              <entry colname=\"col1\">\n                                 <para>Total workload</para>\n                              </entry>\n                              <entry colname=\"col2\">\n                                 <para>\n                                    <internalRef internalRefId=\"id-0011\"/>\n                                 </para>\n                              </entry>\n                           </row>\n                           <row>\n                              <entry colname=\"col1\">\n                                 <para>Estimated time</para>\n                              </entry>\n                              <entry colname=\"col2\">\n                                 <para>\n                                    <internalRef internalRefId=\"id-0012\"/>\n                                 </para>\n                              </entry>\n                           </row>\n                        </tbody>\n                     </tgroup>\n                  </table>\n               </sbTopicContent>\n            </sbTopic>\n            <sbTopic sbTopicType=\"sbtt12\">\n               <title>Weight and Balance</title>\n               <sbTopicContent>\n                  <levelledParaAlts id=\"SPEC-0018\"><!-- EPWG: Added levelledParaAlts --><levelledPara applicRefId=\"app-0002\">\n                        <table>\n                           <tgroup cols=\"4\">\n                              <colspec colname=\"col1\" colwidth=\"20*\"/>\n                              <colspec colname=\"col2\" colwidth=\"10*\"/>\n                              <colspec colname=\"col3\" colwidth=\"10*\"/>\n                              <colspec colname=\"col4\" colwidth=\"60*\"/>\n                              <tbody>\n                                 <row>\n                                    <entry colname=\"col1\">\n                                       <para>Effect on weight</para>\n                                    </entry>\n                                    <entry colname=\"col2\">\n                                       <para>\n                                          <internalRef internalRefId=\"id-0013\"/>\n                                       </para>\n                                    </entry>\n                                 </row>\n                              </tbody>\n                           </tgroup>\n                        </table>\n                     </levelledPara>\n                     <levelledPara applicRefId=\"app-0003\">\n                        <table>\n                           <tgroup cols=\"4\">\n                              <colspec colname=\"col1\" colwidth=\"20*\"/>\n                              <colspec colname=\"col2\" colwidth=\"10*\"/>\n                              <colspec colname=\"col3\" colwidth=\"10*\"/>\n                              <colspec colname=\"col4\" colwidth=\"60*\"/>\n                              <tbody>\n                                 <row>\n                                    <entry colname=\"col1\">\n                                       <para>Effect on weight</para>\n                                    </entry>\n                                    <entry colname=\"col2\">\n                                       <para>\n                                          <internalRef internalRefId=\"id-0014\"/>\n                                       </para>\n                                    </entry>\n                                 </row>\n                              </tbody>\n                           </tgroup>\n                        </table>\n                     </levelledPara>\n                  </levelledParaAlts>\n               </sbTopicContent>\n            </sbTopic>\n            <sbTopic sbTopicType=\"sbtt13\">\n               <title>Electrical Load Data</title>\n               <noInfo/>\n            </sbTopic>\n            <sbTopic sbTopicType=\"sbtt14\">\n               <title>Software Accomplishment Summary</title>\n               <noInfo/>\n            </sbTopic>\n            <sbTopic sbTopicType=\"sbtt15\">\n               <title>Referenced Documentation</title>\n               <sbTopicContent>\n                  <para>Removal of the headset <dmRef>\n                        <dmRefIdent>\n                           <dmCode modelIdentCode=\"S1000DBIKE\"\n                                   systemDiffCode=\"AAA\"\n                                   systemCode=\"DA2\"\n                                   subSystemCode=\"3\"\n                                   subSubSystemCode=\"0\"\n                                   assyCode=\"00\"\n                                   disassyCode=\"00\"\n                                   disassyCodeVariant=\"AA\"\n                                   infoCode=\"520\"\n                                   infoCodeVariant=\"A\"\n                                   itemLocationCode=\"A\"/>\n                        </dmRefIdent>\n                     </dmRef>\n                  </para>\n                  <para>Install of the headset <dmRef>\n                        <dmRefIdent>\n                           <dmCode modelIdentCode=\"S1000DBIKE\"\n                                   systemDiffCode=\"AAA\"\n                                   systemCode=\"DA2\"\n                                   subSystemCode=\"3\"\n                                   subSubSystemCode=\"0\"\n                                   assyCode=\"00\"\n                                   disassyCode=\"00\"\n                                   disassyCodeVariant=\"AA\"\n                                   infoCode=\"720\"\n                                   infoCodeVariant=\"A\"\n                                   itemLocationCode=\"A\"/>\n                        </dmRefIdent>\n                     </dmRef>\n                  </para>\n                  <para>Removal of the stem <dmRef>\n                        <dmRefIdent>\n                           <dmCode modelIdentCode=\"S1000DBIKE\"\n                                   systemDiffCode=\"AAA\"\n                                   systemCode=\"DA2\"\n                                   subSystemCode=\"1\"\n                                   subSubSystemCode=\"0\"\n                                   assyCode=\"00\"\n                                   disassyCode=\"00\"\n                                   disassyCodeVariant=\"AA\"\n                                   infoCode=\"520\"\n                                   infoCodeVariant=\"A\"\n                                   itemLocationCode=\"A\"/>\n                        </dmRefIdent>\n                     </dmRef>\n                  </para>\n                  <para>Install of the stem <dmRef>\n                        <dmRefIdent>\n                           <dmCode modelIdentCode=\"S1000DBIKE\"\n                                   systemDiffCode=\"AAA\"\n                                   systemCode=\"DA2\"\n                                   subSystemCode=\"1\"\n                                   subSubSystemCode=\"0\"\n                                   assyCode=\"00\"\n                                   disassyCode=\"00\"\n                                   disassyCodeVariant=\"AA\"\n                                   infoCode=\"720\"\n                                   infoCodeVariant=\"A\"\n                                   itemLocationCode=\"A\"/>\n                        </dmRefIdent>\n                     </dmRef>\n                  </para>\n                  <para>Testing of the brakes <dmRef>\n                        <dmRefIdent>\n                           <dmCode modelIdentCode=\"BRAKE\"\n                                   systemDiffCode=\"AAA\"\n                                   systemCode=\"DA1\"\n                                   subSystemCode=\"0\"\n                                   subSubSystemCode=\"0\"\n                                   assyCode=\"00\"\n                                   disassyCode=\"00\"\n                                   disassyCodeVariant=\"AA\"\n                                   infoCode=\"341\"\n                                   infoCodeVariant=\"A\"\n                                   itemLocationCode=\"A\"/>\n                        </dmRefIdent>\n                     </dmRef>\n                  </para>\n               </sbTopicContent>\n            </sbTopic>\n            <sbTopic sbTopicType=\"sbtt16\">\n               <title>Documentation Affected</title>\n               <sbTopicContent>\n                  <para>IPD <dmRef>\n                        <dmRefIdent>\n                           <dmCode modelIdentCode=\"S1000DBIKE\"\n                                   systemDiffCode=\"AAA\"\n                                   systemCode=\"D00\"\n                                   subSystemCode=\"0\"\n                                   subSubSystemCode=\"0\"\n                                   assyCode=\"00\"\n                                   disassyCode=\"00\"\n                                   disassyCodeVariant=\"AA\"\n                                   infoCode=\"941\"\n                                   infoCodeVariant=\"A\"\n                                   itemLocationCode=\"D\"/>\n                        </dmRefIdent>\n                     </dmRef>\n                  </para>\n               </sbTopicContent>\n            </sbTopic>\n            <sbTopic sbTopicType=\"sbtt17\">\n               <title>Industry Support Information</title>\n               <sbTopicContent>\n                  <para>For any issue with the fork assembly, please contact your local retailer.</para>\n                  <!-- EPWG add acronymTerm with ref to acronymDefinition --><para>The <acronymTerm internalRefId=\"acr-0001\">UK MoD</acronymTerm> only provides assistance via its network of retailers.</para>\n                  <!-- EPWG add acronymTerm with ref to acronymDefinition --></sbTopicContent>\n            </sbTopic>\n         </sbPlanningInfo>\n         <sbMaterialInfo>\n            <sbMaterialInfoContent>\n               <commonInfo>\n                  <commonInfoDescrParaAlts id=\"SPEC-0016\">\n                     <commonInfoDescrPara applicRefId=\"app-0002\">\n                        <para>Check to order the appropriate telescopic fork with a 140 mm clearance</para>\n                     </commonInfoDescrPara>\n                     <commonInfoDescrPara applicRefId=\"app-0003\">\n                        <para>Check to order the appropriate telescopic fork with a 100 mm clearance</para>\n                     </commonInfoDescrPara>\n                  </commonInfoDescrParaAlts>\n               </commonInfo>\n               <sbMaterialSetList>\n                  <sbMaterialSet applicRefId=\"app-0002\"><!-- EPWG add sbIndustrySupport --><sbIndustrySupport id=\"SPEC-0004\">\n                        <para>Technical support can be requested at:</para>\n                        <enterpriseRef manufacturerCodeValue=\"KZ666\">\n                           <name>World-Bike</name>\n                           <businessUnit>\n                              <businessUnitName>Customer support</businessUnitName>\n                              <businessUnitAddress>\n                                 <street>100, Bike Street</street>\n                                 <city>London</city>\n                                 <country>UK</country>\n                              </businessUnitAddress>\n                           </businessUnit>\n                        </enterpriseRef>\n                     </sbIndustrySupport>\n                     <!-- EPWG end add sbIndustrySupport --><sbMaterialDescr>\n                        <sbMaterialSetRef>\n                           <internalRef internalRefId=\"mat-0001\" internalRefTargetType=\"irtt15\">Saw tool set</internalRef>\n                        </sbMaterialSetRef>\n                        <reqQuantity unitOfMeasure=\"EA\">1</reqQuantity>\n                     </sbMaterialDescr>\n                     <sbMaterialDescr>\n                        <sbMaterialSetRef>\n                           <internalRef internalRefId=\"mat-0002\" internalRefTargetType=\"irtt15\">Supplies</internalRef>\n                        </sbMaterialSetRef>\n                     </sbMaterialDescr>\n                     <sbMaterialDescr>\n                        <sbMaterialSetRef>\n                           <internalRef internalRefId=\"mat-0003\" internalRefTargetType=\"irtt15\">Fork set</internalRef>\n                        </sbMaterialSetRef>\n                        <reqQuantity unitOfMeasure=\"EA\">1</reqQuantity>\n                     </sbMaterialDescr>\n                     <sbMaterialDescr>\n                        <sbMaterialSetRef>\n                           <internalRef internalRefId=\"mat-0005\" internalRefTargetType=\"irtt15\">Removed spare set</internalRef>\n                        </sbMaterialSetRef>\n                     </sbMaterialDescr>\n                     <sbMaterialDescr>\n                        <sbMaterialSetRef>\n                           <internalRef internalRefId=\"mat-0007\" internalRefTargetType=\"irtt15\">Modified spare</internalRef>\n                        </sbMaterialSetRef>\n                     </sbMaterialDescr>\n                     <sbMaterialDescr>\n                        <sbMaterialSetRef>\n                           <internalRef internalRefId=\"mat-0010\" internalRefTargetType=\"irtt15\">Referenced tools</internalRef>\n                        </sbMaterialSetRef>\n                        <reqQuantity>See SB</reqQuantity>\n                     </sbMaterialDescr>\n                     <sbMaterialDescr>\n                        <sbMaterialSetRef>\n                           <internalRef internalRefId=\"mat-0011\" internalRefTargetType=\"irtt15\">Referenced consumables</internalRef>\n                        </sbMaterialSetRef>\n                        <reqQuantity>See SB</reqQuantity>\n                     </sbMaterialDescr>\n                     <sbMaterialDescr>\n                        <sbMaterialSetRef>\n                           <internalRef internalRefId=\"mat-0012\" internalRefTargetType=\"irtt15\">Referenced parts</internalRef>\n                        </sbMaterialSetRef>\n                        <reqQuantity>See SB</reqQuantity>\n                     </sbMaterialDescr>\n                     <sbMaterialDescr>\n                        <sbMaterialSetRef>\n                           <internalRef internalRefId=\"mat-0018\" internalRefTargetType=\"irtt15\">Clean up set</internalRef>\n                        </sbMaterialSetRef>\n                     </sbMaterialDescr>\n                  </sbMaterialSet>\n                  <sbMaterialSet applicRefId=\"app-0003\"><!-- EPWG add sbIndustrySupport --><sbIndustrySupport id=\"SPEC-0005\">\n                        <para>Technical support can be requested at:</para>\n                        <enterpriseRef manufacturerCodeValue=\"KZ666\">\n                           <name>World-Bike</name>\n                           <businessUnit>\n                              <businessUnitName>Customer support</businessUnitName>\n                              <businessUnitAddress>\n                                 <street>100, Bike Street</street>\n                                 <city>London</city>\n                                 <country>UK</country>\n                              </businessUnitAddress>\n                           </businessUnit>\n                        </enterpriseRef>\n                     </sbIndustrySupport>\n                     <!-- EPWG end add sbIndustrySupport --><sbMaterialDescr>\n                        <sbMaterialSetRef>\n                           <internalRef internalRefId=\"mat-0001\" internalRefTargetType=\"irtt15\">Saw tool set</internalRef>\n                        </sbMaterialSetRef>\n                        <reqQuantity unitOfMeasure=\"EA\">1</reqQuantity>\n                     </sbMaterialDescr>\n                     <sbMaterialDescr>\n                        <sbMaterialSetRef>\n                           <internalRef internalRefId=\"mat-0002\" internalRefTargetType=\"irtt15\">Supplies</internalRef>\n                        </sbMaterialSetRef>\n                     </sbMaterialDescr>\n                     <sbMaterialDescr>\n                        <sbMaterialSetRef>\n                           <internalRef internalRefId=\"mat-0004\" internalRefTargetType=\"irtt15\">Fork</internalRef>\n                        </sbMaterialSetRef>\n                        <reqQuantity unitOfMeasure=\"EA\">1</reqQuantity>\n                     </sbMaterialDescr>\n                     <sbMaterialDescr>\n                        <sbMaterialSetRef>\n                           <internalRef internalRefId=\"mat-0006\" internalRefTargetType=\"irtt15\">Removed spare set</internalRef>\n                        </sbMaterialSetRef>\n                     </sbMaterialDescr>\n                     <sbMaterialDescr>\n                        <sbMaterialSetRef>\n                           <internalRef internalRefId=\"mat-0007\" internalRefTargetType=\"irtt15\">Modified spare</internalRef>\n                        </sbMaterialSetRef>\n                     </sbMaterialDescr>\n                     <sbMaterialDescr>\n    